1	#[derive(Clone, Copy, PartialEq, Eq, Debug)]
2	pub enum ItemType {
3	    Sword,
4	    Amulet,
5	    Staff,
6	    Potion,
7	    Rune,
8	    Moonstone,
9	}
10	
11	/// What MHPCO records an item as being made of. The office keeps a material
12	/// on every item it insures, but its policy wording singles out only one:
13	/// the rest it records as an ordinary material and draws no distinction
14	/// between them.
15	#[derive(Clone, Copy, PartialEq, Eq, Debug)]
16	pub enum Material {
17	    Dragon,
18	    Ordinary,
19	}
20	
21	impl Material {
22	    /// The material MHPCO recognises under this name. A name the office draws
23	    /// no distinction by -- steel, silver -- is recorded as ordinary.
24	    pub fn named(name: &str) -> Self {
25	        match name {
26	            "dragon" => Self::Dragon,
27	            _ => Self::Ordinary,
28	        }
29	    }
30	}
31	
32	#[derive(Clone, Copy, Debug)]
33	pub struct Item {
34	    pub item_type: ItemType,
35	    pub material: Material,
36	    pub cursed: bool,
37	    pub enchantment: u32,
38	}
39	
40	impl Item {
41	    pub fn new(item_type: ItemType) -> Self {
42	        Self {
43	            item_type,
44	            material: Material::Ordinary,
45	            cursed: false,
46	            enchantment: 0,
47	        }
48	    }
49	
50	    /// The material MHPCO records the item as being made of.
51	    pub fn made_of(self, material: &str) -> Self {
52	        Self {
53	            material: Material::named(material),
54	            ..self
55	        }
56	    }
57	
58	    pub fn with_enchantment(self, enchantment: u32) -> Self {
59	        Self {
60	            enchantment,
61	            ..self
62	        }
63	    }
64	
65	    pub fn cursed(self) -> Self {
66	        Self {
67	            cursed: true,
68	            ..self
69	        }
70	    }
71	}
